/* Aubry & Vent — Caliber 08
   Dark, hairline-ruled, technical. Serif for language and figures, a tight
   grotesque for labels and data. Colour is nearly absent: German silver on
   graphite, with blued steel for anything the movement is doing. */

:root {
  --ink: #eae7e0;
  --ink-2: #b6b1a7;
  --ink-3: #837d72;
  --ink-4: #565049;

  --bg: #0c0c0d;
  --bg-2: #111112;
  --bg-3: #17171a;

  --rule: rgba(234, 231, 224, 0.11);
  --rule-soft: rgba(234, 231, 224, 0.06);

  --blue: #7d9bd4;
  --blue-deep: #3f5b90;
  --brass: #c2a271;

  --serif: 'Iowan Old Style', 'Hoefler Text', 'Palatino Linotype', Palatino, Georgia,
    'Times New Roman', serif;
  --sans: 'Helvetica Neue', Inter, 'Segoe UI', system-ui, -apple-system, Arial, sans-serif;

  --pad: clamp(1.25rem, 4vw, 4.5rem);
  --max: 78rem;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 5.5rem;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--serif);
  font-size: 17px;
  line-height: 1.62;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

h1,
h2,
h3 {
  font-weight: 400;
  margin: 0;
  letter-spacing: -0.012em;
}

p {
  margin: 0;
}

ul,
ol,
dl {
  margin: 0;
  padding: 0;
  list-style: none;
}

a {
  color: inherit;
}

::selection {
  background: var(--blue-deep);
  color: #fff;
}

:focus-visible {
  outline: 1px solid var(--blue);
  outline-offset: 3px;
}

/* ---------- shared ---------- */

.page {
  max-width: 120rem;
  margin: 0 auto;
  overflow-clip-margin: 1rem;
}

.label,
.eyebrow,
.section-index,
.hero-figures dt,
.stack-edge,
.stack-total,
.alloc-text,
.field label,
.topnav a,
.topcta,
.footer-links,
.footer-mark,
.footer-mail {
  font-family: var(--sans);
  font-size: 0.688rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.section {
  padding: clamp(4.5rem, 10vw, 9rem) var(--pad);
  max-width: var(--max);
  margin: 0 auto;
  border-top: 1px solid var(--rule-soft);
}

.section-head {
  max-width: 46rem;
  margin-bottom: clamp(2.5rem, 6vw, 4.5rem);
}

.section-index {
  color: var(--ink-4);
  margin-bottom: 1.25rem;
}

.section-head h2 {
  font-size: clamp(1.85rem, 4vw, 3rem);
  line-height: 1.1;
}

.section-note {
  margin-top: 1.1rem;
  color: var(--ink-2);
  font-size: 1.02rem;
  max-width: 34rem;
}

[data-reveal] {
  opacity: 0;
  transform: translateY(14px);
  transition: opacity 0.7s ease, transform 0.7s cubic-bezier(0.22, 0.61, 0.36, 1);
}

[data-reveal].is-in {
  opacity: 1;
  transform: none;
}

/* ---------- top bar ---------- */

.topbar {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  gap: 2rem;
  padding: 1rem var(--pad);
  background: rgba(12, 12, 13, 0.78);
  backdrop-filter: blur(14px) saturate(140%);
  border-bottom: 1px solid var(--rule-soft);
}

.wordmark {
  font-family: var(--serif);
  font-size: 1.02rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  text-decoration: none;
  white-space: nowrap;
}

.wordmark span {
  color: var(--brass);
  font-style: italic;
  text-transform: none;
  letter-spacing: 0;
}

.topnav {
  display: flex;
  gap: 1.75rem;
  margin-left: auto;
  color: var(--ink-3);
}

.topnav a {
  text-decoration: none;
  transition: color 0.25s ease;
}

.topnav a:hover {
  color: var(--ink);
}

.topcta {
  text-decoration: none;
  padding: 0.6rem 1.1rem;
  border: 1px solid var(--rule);
  color: var(--ink-2);
  transition: border-color 0.25s ease, color 0.25s ease, background 0.25s ease;
}

.topcta:hover {
  color: var(--ink);
  border-color: var(--blue-deep);
  background: rgba(63, 91, 144, 0.14);
}

@media (max-width: 860px) {
  .topnav {
    display: none;
  }

  .topcta {
    margin-left: auto;
  }
}

/* ---------- hero ---------- */

.hero {
  position: relative;
  padding: clamp(5rem, 13vw, 11rem) var(--pad) clamp(4rem, 9vw, 8rem);
  max-width: var(--max);
  margin: 0 auto;
  overflow: hidden;
}

.hero-inner {
  position: relative;
  z-index: 1;
  max-width: 52rem;
}

.eyebrow {
  color: var(--brass);
  margin-bottom: 2rem;
}

.hero h1 {
  font-size: clamp(1.9rem, 4.6vw, 3.5rem);
  line-height: 1.16;
  text-wrap: balance;
  max-width: 22ch;
  font-size: clamp(1.9rem, 4.6vw, 3.5rem);
}

.hero h1 {
  max-width: none;
}

.lede {
  margin-top: 1.75rem;
  color: var(--ink-2);
  font-size: clamp(1.02rem, 1.6vw, 1.2rem);
  max-width: 38rem;
}

.hero-figures {
  display: flex;
  flex-wrap: wrap;
  gap: 0;
  margin-top: clamp(3rem, 7vw, 5rem);
  border-top: 1px solid var(--rule);
}

.hero-figures > div {
  padding: 1.4rem 2.2rem 0 0;
  margin-right: 2.2rem;
  border-right: 1px solid var(--rule-soft);
  min-width: 8.5rem;
}

.hero-figures > div:last-child {
  border-right: 0;
}

.hero-figures dt {
  color: var(--ink-4);
}

.hero-figures dd {
  margin: 0.5rem 0 0;
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-variant-numeric: lining-nums tabular-nums;
}

/* plate diagram */

.platemark {
  position: absolute;
  right: -14%;
  top: 50%;
  transform: translateY(-50%);
  width: min(60vw, 40rem);
  height: min(60vw, 40rem);
  pointer-events: none;
  opacity: 0.5;
  mask-image: radial-gradient(circle at 50% 50%, #000 42%, transparent 76%);
}

.platemark circle {
  fill: none;
  stroke: rgba(234, 231, 224, 0.16);
  stroke-width: 0.22;
}

.platemark .tick {
  stroke: rgba(234, 231, 224, 0.2);
  stroke-width: 0.22;
}

.platemark .tick-major {
  stroke: rgba(234, 231, 224, 0.4);
  stroke-width: 0.35;
}

.platemark .jewel {
  fill: rgba(194, 162, 113, 0.55);
  stroke: none;
}

.platemark-spin {
  transform-origin: 50px 50px;
  animation: platespin 260s linear infinite;
}

@keyframes platespin {
  to {
    transform: rotate(360deg);
  }
}

@media (max-width: 900px) {
  .platemark {
    right: -30%;
    opacity: 0.3;
  }
}

/* ---------- power path ---------- */

.path {
  border-top: 1px solid var(--rule);
}

.stage {
  display: grid;
  grid-template-columns: 2.75rem minmax(0, 1fr) minmax(0, 17rem);
  gap: clamp(1rem, 3vw, 3rem);
  align-items: start;
  padding: clamp(1.9rem, 3.4vw, 2.9rem) 0;
  border-bottom: 1px solid var(--rule-soft);
  transition: background 0.3s ease;
}

.stage:hover {
  background: linear-gradient(90deg, rgba(125, 155, 212, 0.05), transparent 65%);
}

.stage-rail {
  position: relative;
  align-self: stretch;
  display: flex;
  justify-content: center;
}

.stage-rail::before {
  content: '';
  position: absolute;
  top: -3rem;
  bottom: -3rem;
  width: 1px;
  background: linear-gradient(
    180deg,
    rgba(125, 155, 212, 0.05),
    rgba(125, 155, 212, 0.45),
    rgba(125, 155, 212, 0.05)
  );
}

.stage:first-child .stage-rail::before {
  top: 0.85rem;
}

.stage:last-child .stage-rail::before {
  bottom: calc(100% - 1.1rem);
}

.stage-node {
  position: relative;
  margin-top: 0.7rem;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--bg);
  border: 1px solid var(--blue);
  transition: box-shadow 0.4s ease, background 0.4s ease;
}

.stage.is-in .stage-node {
  background: var(--blue);
  box-shadow: 0 0 0 4px rgba(125, 155, 212, 0.12);
}

.stage-num {
  font-family: var(--sans);
  font-size: 0.688rem;
  letter-spacing: 0.14em;
  color: var(--ink-4);
  margin-bottom: 0.55rem;
}

.stage-body h3 {
  font-size: clamp(1.25rem, 2.2vw, 1.6rem);
  line-height: 1.2;
}

.stage-detail {
  margin-top: 0.6rem;
  color: var(--ink-2);
  max-width: 46ch;
}

.stage-figure {
  font-family: var(--sans);
  font-size: 0.82rem;
  line-height: 1.5;
  letter-spacing: 0.01em;
  color: var(--ink);
  font-variant-numeric: lining-nums tabular-nums;
  padding-left: clamp(0.9rem, 2vw, 1.5rem);
  border-left: 1px solid var(--rule);
  align-self: center;
}

@media (max-width: 780px) {
  .stage {
    grid-template-columns: 1.75rem minmax(0, 1fr);
  }

  .stage-figure {
    grid-column: 2;
    margin-top: 1rem;
    padding-left: 0;
    padding-top: 0.85rem;
    border-left: 0;
    border-top: 1px solid var(--rule);
    color: var(--blue);
  }
}

/* ---------- construction ---------- */

.build {
  display: grid;
  grid-template-columns: minmax(11rem, 17rem) minmax(0, 1fr);
  gap: clamp(2rem, 6vw, 5rem);
  align-items: start;
}

.stack {
  position: sticky;
  top: 7rem;
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
}

.stack-edge {
  color: var(--ink-4);
}

.stack-body {
  height: clamp(15rem, 34vw, 22rem);
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.band {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  width: 100%;
  min-height: 18px;
  padding: 0 0.75rem;
  border: 1px solid var(--rule);
  background: linear-gradient(
    100deg,
    rgba(234, 231, 224, 0.05),
    rgba(234, 231, 224, 0.1) 45%,
    rgba(234, 231, 224, 0.03)
  );
  cursor: default;
  transition: background 0.35s ease, border-color 0.35s ease, transform 0.35s ease;
}

.band::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: repeating-linear-gradient(
    100deg,
    rgba(234, 231, 224, 0.12) 0 1px,
    transparent 1px 4px
  );
  opacity: 0.5;
}

.band.is-active {
  border-color: rgba(125, 155, 212, 0.65);
  background: linear-gradient(
    100deg,
    rgba(125, 155, 212, 0.16),
    rgba(125, 155, 212, 0.3) 45%,
    rgba(125, 155, 212, 0.1)
  );
  transform: translateX(6px);
}

.band-mm {
  position: relative;
  font-family: var(--sans);
  font-size: 0.66rem;
  letter-spacing: 0.1em;
  color: var(--ink-2);
  font-variant-numeric: tabular-nums;
}

.band.is-active .band-mm {
  color: #fff;
}

.stack-total {
  color: var(--ink-3);
  padding-top: 0.6rem;
  border-top: 1px solid var(--rule);
  font-variant-numeric: tabular-nums;
}

.layers {
  display: flex;
  flex-direction: column;
}

.layer {
  padding: clamp(1.2rem, 2.4vw, 1.8rem) 0 clamp(1.2rem, 2.4vw, 1.8rem)
    clamp(1rem, 2.4vw, 1.75rem);
  border-top: 1px solid var(--rule-soft);
  border-left: 1px solid transparent;
  transition: border-color 0.3s ease, opacity 0.3s ease;
  opacity: 0.62;
}

.layer:last-child {
  border-bottom: 1px solid var(--rule-soft);
}

.layer.is-active {
  opacity: 1;
  border-left-color: var(--blue);
}

.layer h3 {
  display: flex;
  align-items: baseline;
  gap: 1rem;
  font-size: clamp(1.1rem, 2vw, 1.35rem);
}

.layer-mm {
  font-family: var(--sans);
  font-size: 0.7rem;
  letter-spacing: 0.12em;
  color: var(--ink-3);
  font-variant-numeric: tabular-nums;
  margin-left: auto;
}

.layer p {
  margin-top: 0.5rem;
  color: var(--ink-2);
  max-width: 52ch;
}

@media (max-width: 760px) {
  .build {
    grid-template-columns: 1fr;
  }

  .stack {
    position: static;
    max-width: 20rem;
  }
}

/* ---------- specification ---------- */

.spec {
  columns: 2;
  column-gap: clamp(2rem, 7vw, 5rem);
  border-top: 1px solid var(--rule);
}

.spec-row {
  break-inside: avoid;
  display: flex;
  align-items: baseline;
  gap: 0.75rem;
  padding: 0.9rem 0;
  border-bottom: 1px solid var(--rule-soft);
}

.spec-row dt {
  font-family: var(--sans);
  font-size: 0.72rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink-3);
  white-space: nowrap;
}

.spec-row::after {
  content: '';
  flex: 1;
  height: 1px;
  background-image: linear-gradient(90deg, var(--rule) 0 1px, transparent 1px 5px);
  background-size: 5px 1px;
  order: 1;
  transform: translateY(-0.28em);
}

.spec-row dd {
  order: 2;
  margin: 0;
  text-align: right;
  font-variant-numeric: lining-nums tabular-nums;
  white-space: nowrap;
}

@media (max-width: 700px) {
  .spec {
    columns: 1;
  }
}

/* ---------- finishes ---------- */

.finishes {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));
  gap: 1px;
  background: var(--rule-soft);
  border: 1px solid var(--rule-soft);
}

.finish {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  padding: clamp(1.6rem, 3vw, 2.4rem);
  background: var(--bg-2);
  transition: background 0.35s ease, box-shadow 0.35s ease;
}

.finish:hover {
  background: var(--bg-3);
}

.finish.is-chosen {
  background: var(--bg-3);
  box-shadow: inset 0 2px 0 0 var(--blue);
}

.finish h3 {
  font-size: 1.3rem;
  line-height: 1.25;
}

.finish-desc {
  color: var(--ink-2);
  font-size: 0.97rem;
}

.finish-price {
  margin-top: auto;
  padding-top: 1.1rem;
  font-size: clamp(1.6rem, 3vw, 2.05rem);
  font-variant-numeric: lining-nums tabular-nums;
  letter-spacing: -0.015em;
}

.finish-price .cur {
  font-family: var(--sans);
  font-size: 0.68rem;
  letter-spacing: 0.16em;
  color: var(--ink-3);
  vertical-align: 0.55em;
  margin-right: 0.35rem;
}

.finish-lead {
  font-family: var(--sans);
  font-size: 0.78rem;
  letter-spacing: 0.04em;
  color: var(--brass);
}

.allocation {
  margin-top: 0.4rem;
}

.alloc-bar {
  height: 2px;
  background: rgba(234, 231, 224, 0.09);
  overflow: hidden;
}

.alloc-bar span {
  display: block;
  height: 100%;
  background: var(--blue);
}

.alloc-text {
  margin-top: 0.7rem;
  color: var(--ink-3);
  letter-spacing: 0.11em;
}

.alloc-text strong {
  color: var(--ink);
  font-weight: 400;
  font-variant-numeric: tabular-nums;
}

.finish-pick {
  margin-top: 1rem;
  font-family: var(--sans);
  font-size: 0.7rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-2);
  background: transparent;
  border: 1px solid var(--rule);
  padding: 0.85rem 1rem;
  cursor: pointer;
  transition: color 0.25s ease, border-color 0.25s ease, background 0.25s ease;
}

.finish-pick:hover {
  color: var(--ink);
  border-color: var(--ink-4);
}

.finish.is-chosen .finish-pick {
  color: #fff;
  border-color: var(--blue-deep);
  background: rgba(63, 91, 144, 0.22);
}

/* ---------- workshop ---------- */

.section--atelier {
  background: var(--bg-2);
  max-width: none;
  border-top: 1px solid var(--rule-soft);
}

.section--atelier > * {
  max-width: var(--max);
  margin-left: auto;
  margin-right: auto;
}

.atelier {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(18rem, 1fr));
  gap: clamp(1.5rem, 4vw, 3rem) clamp(2rem, 5vw, 4rem);
}

.atelier li {
  display: grid;
  grid-template-columns: 2.5rem 1fr;
  align-items: start;
  padding-top: 1.1rem;
  border-top: 1px solid var(--rule);
}

.atelier-num {
  font-family: var(--sans);
  font-size: 0.688rem;
  letter-spacing: 0.14em;
  color: var(--ink-4);
  padding-top: 0.3rem;
}

.atelier li p {
  color: var(--ink-2);
  font-size: 1.04rem;
  max-width: 40ch;
}

/* ---------- reserve ---------- */

.section--reserve {
  border-top: 1px solid var(--rule-soft);
}

.reserve {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 24rem);
  gap: clamp(2.5rem, 7vw, 6rem);
  align-items: start;
}

.reserve-copy h2 {
  font-size: clamp(1.9rem, 4vw, 3rem);
  line-height: 1.1;
}

.reserve-note {
  margin-top: 1.3rem;
  color: var(--ink-2);
  max-width: 34rem;
}

.form,
.confirm {
  border: 1px solid var(--rule);
  background: var(--bg-2);
  padding: clamp(1.5rem, 3vw, 2.2rem);
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  margin-bottom: 1.4rem;
}

.field label {
  color: var(--ink-3);
}

.field input,
.field select {
  font-family: var(--serif);
  font-size: 1rem;
  color: var(--ink);
  background: transparent;
  border: 0;
  border-bottom: 1px solid var(--rule);
  padding: 0.6rem 0;
  border-radius: 0;
  transition: border-color 0.25s ease;
}

.field select {
  appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, var(--ink-3) 50%),
    linear-gradient(135deg, var(--ink-3) 50%, transparent 50%);
  background-position: calc(100% - 9px) calc(50% + 1px), calc(100% - 4px) calc(50% + 1px);
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
  padding-right: 1.6rem;
}

.field select option {
  background: #17171a;
  color: var(--ink);
}

.field input:focus,
.field select:focus {
  outline: none;
  border-bottom-color: var(--blue);
}

.form-summary {
  font-family: var(--sans);
  font-size: 0.78rem;
  letter-spacing: 0.03em;
  color: var(--ink-3);
  padding: 0.9rem 0 1.3rem;
  border-top: 1px solid var(--rule-soft);
}

.form button {
  width: 100%;
  font-family: var(--sans);
  font-size: 0.72rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--bg);
  background: var(--ink);
  border: 1px solid var(--ink);
  padding: 1rem;
  cursor: pointer;
  transition: background 0.25s ease, color 0.25s ease;
}

.form button:hover {
  background: #fff;
}

.confirm {
  border-color: rgba(125, 155, 212, 0.45);
}

.confirm-mark {
  font-family: var(--sans);
  font-size: 0.688rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--blue);
  padding-bottom: 1rem;
  margin-bottom: 1.1rem;
  border-bottom: 1px solid var(--rule);
}

.confirm-text {
  font-size: 1.05rem;
  color: var(--ink);
}

@media (max-width: 820px) {
  .reserve {
    grid-template-columns: 1fr;
  }
}

/* ---------- footer ---------- */

.footer {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 1rem 2.5rem;
  padding: 2.5rem var(--pad) 3.5rem;
  max-width: var(--max);
  margin: 0 auto;
  border-top: 1px solid var(--rule);
  color: var(--ink-4);
}

.footer-mail {
  color: var(--ink-3);
}

.footer-mail a {
  color: var(--ink-2);
  text-decoration: none;
  border-bottom: 1px solid var(--rule);
}

.footer-mail a:hover {
  color: var(--ink);
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 1.75rem;
  margin-left: auto;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  .platemark-spin {
    animation: none;
  }

  [data-reveal] {
    opacity: 1;
    transform: none;
    transition: none;
  }
}

